using System.Collections.Generic;
using System.Linq;
using ROM.UI.Sprint01;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using UnityEngine.UI;
namespace ROM.UI.Gameplay {
// One active-target stage: visual geometry and bone transforms, never gameplay components.
public sealed class RiftTargetPortrait:MonoBehaviour {
 const int Layer=RiftModelView.PreviewLayer;const float Interval=1f/15;
 Camera cameraView;GameObject stage,model;RenderTexture texture;RawImage image;Text fallback;Transform current,visualRoot,origin;float scale=1,nextRender;bool facingRight;
 readonly Dictionary<Transform,Transform> bones=new Dictionary<Transform,Transform>();Renderer[] visuals;
 public string Diagnostics{get;private set;}
 public Transform Source=>current;public bool HasModelPortrait=>model&&image.enabled;public bool CameraActive=>cameraView&&cameraView.enabled;public int PoseUpdates{get;private set;}public int RenderFrames{get;private set;}
 public void Configure(Font font,bool faceRight=false){facingRight=faceRight;image=Child("Animated real target model").gameObject.AddComponent<RawImage>();image.uvRect=faceRight?new Rect(1,0,-1,1):new Rect(0,0,1,1);var aspect=image.gameObject.AddComponent<AspectRatioFitter>();aspect.aspectMode=AspectRatioFitter.AspectMode.FitInParent;aspect.aspectRatio=1;image.raycastTarget=false;image.enabled=false;fallback=Child("Explicit missing portrait").gameObject.AddComponent<Text>();fallback.font=font;fallback.fontSize=11;fallback.alignment=TextAnchor.MiddleCenter;fallback.color=new Color(.8f,.78f,.88f);fallback.text="Sin\nretrato";fallback.raycastTarget=false;fallback.enabled=false;}
 RectTransform Child(string name){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(transform,false);r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.sizeDelta=r.anchoredPosition=Vector2.zero;return r;}
 Transform CopyTransform(Transform source){if(!source)return null;if(bones.TryGetValue(source,out var found))return found;var copy=new GameObject(source.name).transform;copy.gameObject.layer=Layer;copy.SetParent(source.parent&&source.parent.IsChildOf(visualRoot)?CopyTransform(source.parent):model.transform,false);copy.localPosition=source.localPosition;copy.localRotation=source.localRotation;copy.localScale=source.localScale;bones[source]=copy;return copy;}
 public void Show(Transform source,Sprite unused){if(ReferenceEquals(current,source))return;ClearModel();current=source;image.enabled=false;fallback.enabled=source;if(!source){ReleaseStage();return;}
  var character=source.GetComponent<MultiFPS.Gameplay.CharacterInstance>();visualRoot=character&&character.CharacterParent?character.CharacterParent:source;Diagnostics="visual root="+visualRoot.name;var renderers=visualRoot.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&(r is SkinnedMeshRenderer||r is MeshRenderer)&&!r.GetComponent<TextMesh>()&&r.name!="Quest rim (local)").Take(32).ToArray();if(renderers.Length==0)return;
  EnsureStage();model=new GameObject("Selected target visual pose only");model.layer=Layer;model.transform.SetParent(stage.transform,false);bones[visualRoot]=model.transform;var animator=visualRoot.GetComponentInChildren<Animator>();origin=animator?animator.transform:visualRoot;scale=1;model.transform.localScale=visualRoot.lossyScale;model.transform.localRotation=Quaternion.Inverse(origin.rotation)*visualRoot.rotation;
  foreach(var sourceRenderer in renderers){var copy=CopyTransform(sourceRenderer.transform);Renderer renderer=null;if(sourceRenderer is SkinnedMeshRenderer skin){if(!skin.sharedMesh)continue;var clone=copy.gameObject.AddComponent<SkinnedMeshRenderer>();clone.sharedMesh=skin.sharedMesh;clone.bones=skin.bones.Select(CopyTransform).ToArray();clone.rootBone=CopyTransform(skin.rootBone);clone.localBounds=skin.localBounds;clone.updateWhenOffscreen=true;renderer=clone;}else if(sourceRenderer.TryGetComponent<MeshFilter>(out var filter)&&filter.sharedMesh){copy.gameObject.AddComponent<MeshFilter>().sharedMesh=filter.sharedMesh;renderer=copy.gameObject.AddComponent<MeshRenderer>();}if(!renderer)continue;renderer.sharedMaterials=sourceRenderer.sharedMaterials;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;}
  visuals=model.GetComponentsInChildren<Renderer>();if(visuals.Length==0){Diagnostics="No visual geometry copied";ClearModel();return;}var bounds=renderers[0].bounds;foreach(var renderer in renderers)bounds.Encapsulate(renderer.bounds);Diagnostics="source bounds="+bounds+" renderers="+renderers.Length+" copied="+visuals.Length;if(bounds.size.y<.001f){ClearModel();return;}scale=2/bounds.size.y;model.transform.localScale=visualRoot.lossyScale*scale;model.transform.localPosition=-(Quaternion.Inverse(origin.rotation)*(bounds.center-visualRoot.position))*scale+Vector3.up;image.texture=texture;image.enabled=true;fallback.enabled=false;nextRender=0;SyncPose();FrameCamera();
 }
 Bounds Bounds(){var bounds=visuals[0].bounds;foreach(var renderer in visuals)if(renderer)bounds.Encapsulate(renderer.bounds);return bounds.size.y>.01f?bounds:new Bounds(stage.transform.position+Vector3.up,new Vector3(1,2,1));}
 void SyncPose(){foreach(var pair in bones){if(!pair.Key||!pair.Value||pair.Key==visualRoot)continue;pair.Value.localPosition=pair.Key.localPosition;pair.Value.localRotation=pair.Key.localRotation;pair.Value.localScale=pair.Key.localScale;}if(visualRoot&&origin){model.transform.localScale=visualRoot.lossyScale*scale;model.transform.localRotation=Quaternion.Inverse(origin.rotation)*visualRoot.rotation;}PoseUpdates++;}
 void FrameCamera(){var bounds=Bounds();float radius=Mathf.Max(.2f,bounds.size.y*.29f);var focus=new Vector3(bounds.center.x,bounds.min.y+bounds.size.y*.77f,bounds.center.z);cameraView.orthographicSize=radius;cameraView.transform.position=focus+new Vector3(radius*.35f,radius*.08f,radius*4);cameraView.transform.LookAt(focus);}
 void EnsureStage(){if(stage)return;stage=new GameObject(facingRight?"Player portrait stage":"Single target portrait stage");stage.transform.position=new Vector3(facingRight?16040:16000,-8000,16000);stage.layer=Layer;var c=new GameObject(facingRight?"Player portrait camera":"Target portrait camera");c.transform.SetParent(stage.transform,false);cameraView=c.AddComponent<Camera>();c.AddComponent<RiftInspectionCamera>();cameraView.orthographic=true;cameraView.cullingMask=1<<Layer;cameraView.clearFlags=CameraClearFlags.SolidColor;cameraView.backgroundColor=Color.clear;cameraView.nearClipPlane=.01f;cameraView.farClipPlane=20;cameraView.allowHDR=false;var data=cameraView.GetUniversalAdditionalCameraData();data.renderPostProcessing=false;data.volumeLayerMask=1<<Layer;data.antialiasing=AntialiasingMode.None;data.requiresColorOption=CameraOverrideOption.Off;data.requiresDepthOption=CameraOverrideOption.Off;texture=new RenderTexture(128,128,24,RenderTextureFormat.ARGB32);texture.Create();cameraView.targetTexture=texture;
  var key=new GameObject("Target-stage-only key").AddComponent<Light>();key.transform.SetParent(stage.transform,false);key.transform.localPosition=new Vector3(1.5f,3,3);key.transform.LookAt(stage.transform.position+Vector3.up*1.5f);key.type=LightType.Spot;key.spotAngle=85;key.range=8;key.intensity=20;key.color=new Color(.88f,.92f,1);key.cullingMask=1<<Layer;key.shadows=LightShadows.None;
 }
 void LateUpdate(){if(!current||!model||!image.enabled){if(cameraView)cameraView.enabled=false;return;}SyncPose();bool render=Time.unscaledTime>=nextRender;cameraView.enabled=render;if(render){nextRender=Time.unscaledTime+Interval;FrameCamera();RenderFrames++;}}
 void ClearModel(){if(cameraView)cameraView.enabled=false;if(model)Destroy(model);model=null;visuals=null;bones.Clear();}
 void OnDisable(){if(cameraView)cameraView.enabled=false;}
 void ReleaseStage(){if(texture){texture.Release();Destroy(texture);texture=null;}if(stage)Destroy(stage);stage=null;cameraView=null;}
 void OnDestroy(){ClearModel();ReleaseStage();}
}
}